pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(t1 > 0);
        vm.warp(t1);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.f{value: 10 ether}();

        // General rule: a call completing at timestamp T stores T, so a second
        // call at the SAME timestamp T violates block.timestamp > pastBlockTime
        // and must revert in the reference.
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok;
        try c.f{value: 10 ether}() { ok = true; } catch { ok = false; }

        assertTrue(!ok, "second call at same timestamp must revert");
    }
}

