        ts = bound(ts, 1, type(uint48).max);
        blk = bound(blk, 1, type(uint64).max);
        // avoid the payout branch so the call always succeeds regardless of balance
        vm.assume(blk % 15 != 0);
        // choose a block number that differs from the timestamp so the two versions diverge
        vm.assume(blk != ts);

        vm.roll(blk);
        vm.warp(ts);

        address actor = address(0xABCD);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // General rule: pastBlockTime records the block TIMESTAMP of the last successful call.
        assertTrue(c.pastBlockTime() == ts);
    }
}

