pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 t2, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(t1 >= 1);
        vm.assume(t2 > t1); // strictly later timestamp (so t2 >= t1 + 1)

        vm.deal(actor, 20 ether);

        vm.warp(t1);
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1); // first call is always admissible

        vm.warp(t2);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        // General rule: a second call at any strictly later timestamp succeeds.
        assertTrue(ok2);
    }
}

