pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockSeed, uint256 ts) public {
        // pick a block number that is a multiple of 15 so the payout branch runs
        uint256 bn = bound(blockSeed, 15, 1_000_000);
        bn -= bn % 15;
        vm.roll(bn);
        vm.warp(bound(ts, 2, 1e12));

        // adversarial counterparty: a contract that reverts when it receives the payout
        Reverter r = new Reverter();
        vm.deal(address(r), 10 ether);

        r.attack(address(c)); // sends exactly 10 ether, c's transfer back to r fails

        // General rule: even when the payout transfer fails, pastBlockTime was
        // already updated to this call's block timestamp.
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }

    function attack(address target) external payable {
        (bool ok,) = target.call{value: 10 ether}("");
        ok; // swallow the revert that bubbles up from the failing payout transfer
    }
}

