pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public { c = new C{value: 10 ether}(); caller = new Caller(address(c)); }

    function testFuzz_property(uint256 ts, uint256 bn) public {
        // admissible domain: strictly increasing timestamp, arbitrary block number
        ts = bound(ts, c.pastBlockTime() + 1, type(uint64).max);
        bn = bound(bn, 0, type(uint64).max);
        vm.warp(ts);
        vm.roll(bn);

        // adversarial counterparty: recipient that reverts when it receives the payout
        vm.deal(address(caller), 10 ether);

        bool ok;
        try caller.ping{value: 10 ether}() { ok = true; } catch { ok = false; }

        // general rule: the call succeeds and pastBlockTime records this timestamp
        assertTrue(ok && c.pastBlockTime() == ts);
    }
}

contract Caller {
    C c;
    constructor(address _c) { c = C(_c); }
    function ping() external payable {
        (bool s, ) = address(c).call{value: msg.value}("");
        require(s, "forward failed");
    }
    receive() external payable { revert(); }
}

