pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 ts, bool adversarialPayout) public {
        // wide admissible domain: block number aligned so block.number % 15 == 0,
        // timestamp strictly greater than pastBlockTime (0 initially)
        blockNum = bound(blockNum, 0, 1_000_000);
        ts = bound(ts, 1, block.timestamp + 1_000_000_000);

        vm.roll(blockNum - (blockNum % 15));
        vm.warp(ts);

        // adversarial counterparty: a recipient whose receive() reverts, so the
        // payout transfer inside the fallback fails
        Reverter recipient = new Reverter();
        vm.deal(address(recipient), 10 ether);

        address actor = adversarialPayout ? address(recipient) : address(this);

        vm.prank(actor);
        (bool ok, ) = payable(address(c)).call{value: 10 ether}("");

        // general rule: for any admissible call, either the call reverts, or the
        // call completes AND pastBlockTime was advanced to this call's timestamp.
        // The mutant, when the payout transfer fails, completes its execution path
        // without having durably updated pastBlockTime for such runs, breaking the
        // invariant for some input the fuzzer can choose.
        assertTrue(!ok || c.pastBlockTime() == block.timestamp);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
}

