pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts) public {
        // keep the timestamp admissible: strictly greater than the last recorded one
        vm.warp(bound(ts, c.pastBlockTime() + 1, type(uint64).max));
        // land on a block where the payout branch triggers (block.number % 15 == 0)
        vm.roll(block.number + (15 - (block.number % 15)));

        // adversarial recipient whose fallback reverts, so the payout transfer fails
        Reverter r = new Reverter();
        vm.deal(address(r), 10 ether);
        vm.prank(address(r));
        (bool ok, ) = address(c).call{value: 10 ether}("");

        // General rule: for every admissible input the interaction completes and
        // c.pastBlockTime() equals block.timestamp afterwards.
        assertTrue(ok && c.pastBlockTime() == block.timestamp);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }

    receive() external payable {
        revert();
    }
}
